mapper.select:
SELECT EXISTS(SELECT 1 FROM document d JOIN document_index_version v ON v.document_id=d.id
WHERE d.id=#{task.documentId} AND v.id=#{task.indexVersionId}
AND d.active_version_id IS NULL AND (v.status='BUILDING' OR (#{task.status}='FAILED' AND v.status IN ('VERIFIED','FAILED'))) AND v.published_at IS NULL)

mapper.update:
UPDATE document_import_task SET status='FAILED',last_error_code=#{code},
last_error_message=#{message},lease_owner=NULL,lease_until=NULL,
next_retry_at=statement_timestamp()+(#{retryMillis} * interval '1 millisecond')NULL,updated_at=statement_timestamp()
WHERE id=#{claim.taskId} AND document_id=#{claim.documentId} AND index_version_id=#{claim.indexVersionId}
AND status='RUNNING' AND lease_owner=#{claim.leaseOwner} AND claim_epoch=#{claim.claimEpoch}
AND lease_until > statement_timestamp()
